import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · Lesson 56 Faster than sound!","description":"学习 比较级与比较范围，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 56 Faster than sound!","description":"学习 比较级与比较范围，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 比较级与比较范围，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 55 Not a gold mine","link":"/life/english/new-concept/book-2/unit-03/lesson-055"},"next":{"text":"第二册：实践与进步 · Lesson 57 Can I help you, madam?","link":"/life/english/new-concept/book-2/unit-03/lesson-057"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 55 Not a gold mine","link":"/life/english/new-concept/book-2/unit-03/lesson-055"},"next":{"text":"第二册：实践与进步 · Lesson 57 Can I help you, madam?","link":"/life/english/new-concept/book-2/unit-03/lesson-057"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/lesson-056.md","filePath":"life/english/new-concept/book-2/unit-03/lesson-056.md"}'),s={name:"life/english/new-concept/book-2/unit-03/lesson-056.md"};function r(i,e,l,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-56-faster-than-sound" tabindex="-1">第二册：实践与进步 · Lesson 56 Faster than sound! <a class="header-anchor" href="#第二册-实践与进步-·-lesson-56-faster-than-sound" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 56 Faster than sound!&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>赛车速度创造纪录，但传言中的数字需要清楚单位和来源；练习比较级修饰与范围。本课的语言观察是：much faster 表差异大，a little faster 表差异小；不能说 very faster。比较速度时，时间、距离和单位必须对应。完成学习后，请比较两款车辆或设备，给出速度优势及一个代价，不编造真实品牌数据。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>speed</td><td>/spiːd/</td><td>n.</td><td>速度</td><td>at high speed</td></tr><tr><td>sound</td><td>/saʊnd/</td><td>n.</td><td>声音</td><td>the speed of sound</td></tr><tr><td>race</td><td>/reɪs/</td><td>n.</td><td>比赛</td><td>win a race</td></tr><tr><td>wheel</td><td>/wiːl/</td><td>n.</td><td>轮子</td><td>a spare wheel</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>at a speed of — 以……的速度，后接数值单位</li><li>break a record — 打破纪录</li></ul><h2 id="语法讲解-比较级与比较范围" tabindex="-1">语法讲解：比较级与比较范围 <a class="header-anchor" href="#语法讲解-比较级与比较范围" aria-label="Permalink to &quot;语法讲解：比较级与比较范围&quot;">​</a></h2><p>比较两者时通常用比较级和 than；在明确的三者或更多成员中选出极值时通常用最高级。短形容词多加 -er/-est，较长形容词多用 more/most，good 与 bad 则是不规则变化。as ... as 中间用原级，否定形式表示不及。比较对象应属于同一类，范围和参照点必须清楚，不能只看到中文“最”就省掉比较范围。本课应用：much faster 表差异大，a little faster 表差异小；不能说 very faster。比较速度时，时间、距离和单位必须对应。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The new car was much faster than the team&#39;s previous model.</p></blockquote><p>新车比车队之前的车型快得多。</p><p>much 修饰比较级 faster，than 后明确比较对象；previous model 与 new car 都指车型。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>more faster 重复比较标记；用 faster 或 much faster。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>重读 much faster 与 sooner，注意 previous 的重音在第一音节。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The new car was much faster than the team&#39;s previous model. However, its tyres wore out sooner. The engineers chose reliability for the next race.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>比较两款车辆或设备，给出速度优势及一个代价，不编造真实品牌数据。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：much 修饰比较级 faster，than 后明确比较对象；previous model 与 new car 都指车型。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：more faster 重复比较标记；用 faster 或 much faster。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选 very/much：The car was ___ faster.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> much</p><p><strong>解析：</strong> much 可以修饰比较级，very 通常不直接修饰比较级。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>下一场比赛工程师优先考虑什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Reliability.</p><p><strong>解析：</strong> however 后说明速度提升伴随轮胎耐用性问题。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>改正：This model is more faster than that one。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> This model is faster than that one.</p><p><strong>解析：</strong> 比较级不能同时用 more 和 -er。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：比较级与比较范围。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-055">上一课</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-057">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=a(s,[["render",r]]);export{p as __pageData,m as default};
